(2, 'sophia_film', 'sophia@cineverse.io', 'scrypt:a9c1e0d3b4f5e6a7b8c9d0e1f2a3b4c5:b5aca4f901fde61bf3b6f717b8689609c4dc177d3b3b37a5e87641825edacb178bc4577c685cbbec7967ef206ca3588062552c2f368f3777ce1d75c0ea1ff801', 'Sophia Chen', 'Film critic & festival juror. Huge fan of Denis Villeneuve and Bong Joon-ho.', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=150', 'https://images.unsplash.com/photo-1536440136628-849c177e76a1?w=1200'),
(3, 'marcus_v', 'marcus@cineverse.io', 'scrypt:a9c1e0d3b4f5e6a7b8c9d0e1f2a3b4c5:b5aca4f901fde61bf3b6f717b8689609c4dc177d3b3b37a5e87641825edacb178bc4577c685cbbec7967ef206ca3588062552c2f368f3777ce1d75c0ea1ff801', 'Marcus Vance', 'Screenwriter in Los Angeles. Dissecting cinematography and narrative structure.', 'https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?w=150', 'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?w=1200'),
(4, 'elena_r', 'elena@cineverse.io', 'scrypt:a9c1e0d3b4f5e6a7b8c9d0e1f2a3b4c5:b5aca4f901fde61bf3b6f717b8689609c4dc177d3b3b37a5e87641825edacb178bc4577c685cbbec7967ef206ca3588062552c2f368f3777ce1d75c0ea1ff801', 'Elena Rostov', 'Visual effects artist & sound designer. Audio-visual immersion is everything.', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?w=150', 'https://images.unsplash.com/photo-1517604931442-7e0c8ed2963c?w=1200'),
(5, 'david_m', 'david@cineverse.io', 'scrypt:a9c1e0d3b4f5e6a7b8c9d0e1f2a3b4c5:b5aca4f901fde61bf3b6f717b8689609c4dc177d3b3b37a5e87641825edacb178bc4577c685cbbec7967ef206ca3588062552c2f368f3777ce1d75c0ea1ff801', 'David Miller', 'Retro movie collector & popcorn movie lover. Nolan and Tarantino buff.', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150', 'https://images.unsplash.com/photo-1478760329108-5c3ed9d495a0?w=1200'),
(6, 'chloe_b', 'chloe@cineverse.io', 'scrypt:a9c1e0d3b4f5e6a7b8c9d0e1f2a3b4c5:b5aca4f901fde61bf3b6f717b8689609c4dc177d3b3b37a5e87641825edacb178bc4577c685cbbec7967ef206ca3588062552c2f368f3777ce1d75c0ea1ff801', 'Chloe Bennett', 'Animation geek and indie drama specialist. Studio Ghibli forever.', 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=150', 'https://images.unsplash.com/photo-1524712245354-2c4e5e7121c0?w=1200')
INSERT INTO movies (tmdb_id, title, tagline, overview, release_date, runtime, poster_url, backdrop_url, trailer_url, director) VALUES
(27205, 'Inception', 'Your mind is the scene of the crime.', 'A thief who steals corporate secrets through the use of dream-sharing technology is given the inverse task of planting an idea into the mind of a C.E.O.', '2010-07-16', 148, 'https://image.tmdb.org/t/p/w500/xlaY2zyzMfkhk0HSC5VUwzoZPU1.jpg', 'https://image.tmdb.org/t/p/original/8ZTVqvKDQ8emSGUEMjsS4yHAwrp.jpg', 'https://www.youtube.com/watch?v=YoHD9XEInc0', 'Christopher Nolan'),
(157336, 'Interstellar', 'Mankind was born on Earth. It was never meant to die here.', 'The adventures of a group of explorers who make use of a newly discovered wormhole to surpass the limitations on human space travel.', '2014-11-05', 169, 'https://image.tmdb.org/t/p/w500/yQvGrMoipbRoddT0ZR8tPoR7NfX.jpg', 'https://image.tmdb.org/t/p/original/vgnoBSVzWAV9sNQUORaDGvDp7wx.jpg', 'https://www.youtube.com/watch?v=zSWdZVtXT7E', 'Christopher Nolan'),
(155, 'The Dark Knight', 'Why So Serious?', 'Batman raises the stakes in his war on crime with the help of Lt. Jim Gordon and District Attorney Harvey Dent.', '2008-07-18', 152, 'https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg', 'https://image.tmdb.org/t/p/original/9FE5eD92WfVCiivM9Pq9GVSrlWk.jpg', 'https://www.youtube.com/watch?v=EXeTwQWrcwY', 'Christopher Nolan'),
(693134, 'Dune: Part Two', 'Long live the fighters.', 'Follow the mythic journey of Paul Atreides as he unites with Chani and the Fremen while on a warpath of revenge.', '2024-03-01', 166, 'https://image.tmdb.org/t/p/w500/6izwz7rsy95ARzTR3poZ8H6c5pp.jpg', 'https://image.tmdb.org/t/p/original/eZ239CUp1d6OryZEBPnO2n87gMG.jpg', 'https://www.youtube.com/watch?v=Way9Dexny3w', 'Denis Villeneuve'),
(872585, 'Oppenheimer', 'The world forever changes.', 'The story of J. Robert Oppenheimer’s role in the development of the atomic bomb during World War II.', '2023-07-21', 180, 'https://image.tmdb.org/t/p/w500/8Gxv8gSFCU0XGDykEGv7zR1n2ua.jpg', 'https://image.tmdb.org/t/p/original/neeNHeXjMF5fXoCJRsOmkNGC7q.jpg', 'https://www.youtube.com/watch?v=uYPbbksJxIg', 'Christopher Nolan'),
(496243, 'Parasite', 'Act like you own the place.', 'All unemployed, Ki-taeks family takes peculiar interest in the wealthy and glamorous Parks for their livelihood.', '2019-10-11', 132, 'https://image.tmdb.org/t/p/w500/7IiTTgloJzvGI1TAYymCfbfl3vT.jpg', 'https://image.tmdb.org/t/p/original/vbC0rzdrb7Ohc2TkbEbxtOABECe.jpg', 'https://www.youtube.com/watch?v=5xH0RzeSojI', 'Bong Joon-ho'),
(129, 'Spirited Away', 'Nothing that happens is ever forgotten, even if you cant remember it.', 'A young girl, Chihiro, becomes trapped in a strange new world of spirits.', '2001-07-20', 125, 'https://image.tmdb.org/t/p/w500/39wmItIWsg5sZMyRUHLkWBcuVCM.jpg', 'https://image.tmdb.org/t/p/original/dyJvKsNs2KP8qQnAXbRwDjblViy.jpg', 'https://www.youtube.com/watch?v=ByXuk9QqQkk', 'Hayao Miyazaki'),
(680, 'Pulp Fiction', 'Just because you are a character doesnt mean you have character.', 'A burger-loving hit man, his philosophical partner, a drug-addled gangsters moll and a washed-up boxer converge.', '1994-10-14', 154, 'https://image.tmdb.org/t/p/w500/vQWk5YBFWF4bZaofAbv0tShwBvQ.jpg', 'https://image.tmdb.org/t/p/original/suaEOtk1N1sgg2MTM7oZd2cfVp3.jpg', 'https://www.youtube.com/watch?v=s7EdQ4FqbhY', 'Quentin Tarantino'),
(603, 'The Matrix', 'Welcome to the Real World.', 'Set in the 22nd century, The Matrix tells the story of a computer hacker who joins a group of underground insurgents.', '1999-03-31', 136, 'https://image.tmdb.org/t/p/w500/dXNAPwY7VrqMAo51EKhhCJfaGb5.jpg', 'https://image.tmdb.org/t/p/original/tlm8UkiQsitc8rSuIAscQDCnP8d.jpg', 'https://www.youtube.com/watch?v=vKQi3bBA1y8', 'Lana Wachowski'),
(244786, 'Whiplash', 'The road to greatness can take you to the edge.', 'Under the direction of a ruthless instructor, a talented young drummer begins to pursue perfection at any cost.', '2014-10-10', 107, 'https://image.tmdb.org/t/p/w500/7fn624j5lj3xTme2SgiLCeuedmO.jpg', 'https://image.tmdb.org/t/p/original/wbQa0EnWUyRzQ5d1pHLNRlmsCUP.jpg', 'https://www.youtube.com/watch?v=7d_jQycdQGo', 'Damien Chazelle'),
(550, 'Fight Club', 'Mischief. Mayhem. Soap.', 'A ticking-time-bomb insomniac and a slippery soap salesman channel primal male aggression.', '1999-10-15', 139, 'https://image.tmdb.org/t/p/w500/jSziioSwPVrOy9Yow3XhWIBDjq1.jpg', 'https://image.tmdb.org/t/p/original/c6OLXfKAk5BKeR6broC8pYiCquX.jpg', 'https://www.youtube.com/watch?v=qtRKdV9eiGw', 'David Fincher'),
(569094, 'Spider-Man: Across the Spider-Verse', 'Its how you wear the mask that matters.', 'After reuniting with Gwen Stacy, Brooklyn’s full-time, friendly neighborhood Spider-Man is catapulted across the Multiverse.', '2023-06-02', 140, 'https://image.tmdb.org/t/p/w500/8Vt6mWEReuy4Of61Lnj5Xj704m8.jpg', 'https://image.tmdb.org/t/p/original/kVd3a9YeLGkoeR50jGEXM6EqseS.jpg', 'https://www.youtube.com/watch?v=cqGjhVJWtEg', 'Joaquim Dos Santos'),
(335984, 'Blade Runner 2049', 'Theres still a page left.', 'Thirty years after the events of the first film, a new blade runner unearths a long-buried secret.', '2017-10-06', 164, 'https://image.tmdb.org/t/p/w500/gajva2L0rPYkEWjzgFlBXCAVBE5.jpg', 'https://image.tmdb.org/t/p/original/gNdLJU9TxrpGx4dkZidjys3fyy0.jpg', 'https://www.youtube.com/watch?v=gCcx85zbxz4', 'Denis Villeneuve'),
(545611, 'Everything Everywhere All at Once', 'The universe is so much bigger than you realize.', 'An aging Chinese immigrant is swept up in an insane adventure across universes.', '2022-03-25', 139, 'https://image.tmdb.org/t/p/w500/u68AjlvlutfEIcpmbYpKcdi09ut.jpg', 'https://image.tmdb.org/t/p/original/ss0Os3uWJfQAENILHZUdX8Tt1OC.jpg', 'https://www.youtube.com/watch?v=wxN1T1uxQ2g', 'Daniel Kwan'),
(120467, 'The Grand Budapest Hotel', 'A comprehensive and hilarious romp through wartime Europe.', 'The adventures of Gustave H, a legendary concierge at a famous European hotel between the wars.', '2014-03-07', 100, 'https://image.tmdb.org/t/p/w500/eWdyYQreja6JGCzqHWXpWHDrrPo.jpg', 'https://image.tmdb.org/t/p/original/9udCLTxTFl28RxnK8Q05E154ZGa.jpg', 'https://www.youtube.com/watch?v=1Fg5iWmQjwk', 'Wes Anderson'),
(238, 'The Godfather', 'An offer you cant refuse.', 'Spanning the years 1945 to 1955, a chronicle of the fictional Italian-American Corleone crime family.', '1972-03-24', 175, 'https://image.tmdb.org/t/p/w500/3bhkrj58Vtu7enYsRolD1fZdja1.jpg', 'https://image.tmdb.org/t/p/original/tSPT36ZKlP2WVHJLM4cQPLSzv3b.jpg', 'https://www.youtube.com/watch?v=sY1S34973zA', 'Francis Ford Coppola'),
(98, 'Gladiator', 'What we do in life echoes in eternity.', 'In the year 180, the death of emperor Marcus Aurelius throws the Roman Empire into chaos.', '2000-05-05', 155, 'https://image.tmdb.org/t/p/w500/wN2xWp1eIwCKOD0BHTcErTBv1Uq.jpg', 'https://image.tmdb.org/t/p/original/jhk6D8pim3yaByu1801kMoxXFaX.jpg', 'https://www.youtube.com/watch?v=owK1qxDselE', 'Ridley Scott'),
(329865, 'Arrival', 'Language is the first weapon drawn.', 'Taking place after alien crafts land around the world, an expert linguist is recruited by the military.', '2016-11-11', 116, 'https://image.tmdb.org/t/p/w500/pEzNVQfdzYDzVK0XqxERIw2x2se.jpg', 'https://image.tmdb.org/t/p/original/8MUZz7oPXQftFTslZpRP3CVMOoq.jpg', 'https://www.youtube.com/watch?v=tFMo3UJ4B4g', 'Denis Villeneuve'),
(313369, 'La La Land', 'Heres to the fools who dream.', 'Mia, an aspiring actress, and Sebastian, a dedicated jazz musician, are struggling to make ends meet.', '2016-12-09', 128, 'https://image.tmdb.org/t/p/w500/uDO8zWDhfWwoFdKS4fzkUJt0Rf0.jpg', 'https://image.tmdb.org/t/p/original/nlPCdZlHtRNcF6C9hzUH4ebmV1w.jpg', 'https://www.youtube.com/watch?v=0pdqf4P9MB8', 'Damien Chazelle'),
(438631, 'Dune: Part One', 'It begins.', 'Paul Atreides must travel to the most dangerous planet in the universe to ensure the future of his family.', '2021-10-22', 155, 'https://image.tmdb.org/t/p/w500/v1tRXZ4JtD2Iv6fjkPvT4GiwslV.jpg', 'https://image.tmdb.org/t/p/original/h3HsfV8Kn9Sz2QWUYYdP5ya23hx.jpg', 'https://www.youtube.com/watch?v=8g18jFHCLXk', 'Denis Villeneuve'),
(1021, 'Schindler''s List', 'Whoever saves one life, saves the world entire.', 'In German-occupied Poland during World War II, industrialist Oskar Schindler gradually becomes concerned for his Jewish workforce after witnessing their persecution by the Nazis.', '1993-12-15', 195, 'https://image.tmdb.org/t/p/w500/sF1U4EUQS8YHUYjNl3pMGNIQyr0.jpg', 'https://image.tmdb.org/t/p/original/zb6fM1CX41D9rF9hdgclu0peUmy.jpg', 'https://www.youtube.com/watch?v=gG22XNhtnoY', 'Steven Spielberg'),
(1022, 'The Shawshank Redemption', 'Fear can hold you prisoner. Hope can set you free.', 'Over the course of several years, two convicts form a friendship, seeking consolation and, eventually, redemption through basic compassion.', '1994-09-23', 142, 'https://image.tmdb.org/t/p/w500/9cqNxx0GxF0bflZmeSMuL5tnGzr.jpg', 'https://image.tmdb.org/t/p/original/zfbjgQE1uSd9wiPTX4VzsLi0rGG.jpg', 'https://www.youtube.com/watch?v=PLl99DlL6b4', 'Frank Darabont'),
(1023, 'Forrest Gump', 'The world will never be the same once you have seen it through the eyes of Forrest Gump.', 'A man with a low IQ has accomplished great things in his life and been present during significant historic events—in each case, far exceeding what anyone imagined possible.', '1994-07-06', 142, 'https://image.tmdb.org/t/p/w500/Cw4hIUIAmSYfK9QfaUW5igp9La.jpg', 'https://image.tmdb.org/t/p/original/66Kn4XWhkuPkJxOJyPEx4U2CUfN.jpg', 'https://www.youtube.com/watch?v=bLvqoHBptjg', 'Robert Zemeckis'),
(1024, 'The Lord of the Rings: The Return of the King', 'The eye of the enemy is moving.', 'As armies mass for a final battle that will decide the fate of the world, one member of the Fellowship of the Ring is revealed as the noble heir to the throne of Men.', '2003-12-17', 201, 'https://image.tmdb.org/t/p/w500/rCzpDGLbOoPwLjy3OAm5NUPOTrC.jpg', 'https://image.tmdb.org/t/p/original/2u7zbn8EudG6kLlBzUYqP8RyFU4.jpg', 'https://www.youtube.com/watch?v=r5X-hFf6Bwo', 'Peter Jackson'),
(1025, 'Star Wars: Episode V - The Empire Strikes Back', 'The Adventure Continues...', 'After the Rebels are brutally overpowered by the Empire on the ice planet Hoth, Luke Skywalker begins Jedi training with Yoda, while his friends are pursued across the galaxy by Darth Vader.', '1980-05-21', 124, 'https://image.tmdb.org/t/p/w500/nNAeTmF4CtdSgMDplXTDPOpYzsX.jpg', 'https://image.tmdb.org/t/p/original/k9pshruhCpJAdH9RaGJO6jaWQ4X.jpg', 'https://www.youtube.com/watch?v=JNwNXF9Y6kY', 'Irvin Kershner'),
(1026, 'Goodfellas', 'Three Decades of Life in the Mafia.', 'The story of Henry Hill and his life in the mafia, covering his relationship with his wife Karen and his mob partners Jimmy Conway and Tommy DeVito.', '1990-09-19', 145, 'https://image.tmdb.org/t/p/w500/9OkCLM73MIU2CrKZbqiT8Ln1wY2.jpg', 'https://image.tmdb.org/t/p/original/gILte6Zd7m1YneIr6MVhh30S9pr.jpg', 'https://www.youtube.com/watch?v=2ilzidi_J8Q', 'Martin Scorsese'),
(1027, 'The Silence of the Lambs', 'To enter the mind of a killer she must challenge the mind of a madman.', 'A young F.B.I. cadet must receive the help of an incarcerated and manipulative cannibal killer to help catch another serial killer, a madman who skins his victims.', '1991-02-14', 118, 'https://image.tmdb.org/t/p/w500/uS9m8OBk1A8eM9I042bx8XXpqAq.jpg', 'https://image.tmdb.org/t/p/original/aYcnDyLMnpKce1FOYUpZrXtgUye.jpg', 'https://www.youtube.com/watch?v=W6Mm8Sbe__o', 'Jonathan Demme'),
(1028, 'Se7en', 'Seven deadly sins. Seven ways to die.', 'Two detectives, a rookie and a veteran, hunt a serial killer who uses the seven deadly sins as his motives.', '1995-09-22', 127, 'https://image.tmdb.org/t/p/w500/191nKfP0ehp3uIvWqgPbFmI4lv9.jpg', 'https://image.tmdb.org/t/p/original/i5H7zusQGsysGQ8i6P361Vnr0n2.jpg', 'https://www.youtube.com/watch?v=znmZoVkCjpI', 'David Fincher'),
(1029, 'City of God', 'Fight and you will never survive. Run and you will never escape.', 'In the slums of Rio, two kids'' paths diverge: one struggles to become a photographer, while the other becomes a kingpin.', '2002-08-30', 130, 'https://image.tmdb.org/t/p/w500/k7eYdWvhYQyRQoU2TB2A2Xu2TfD.jpg', 'https://image.tmdb.org/t/p/original/uvitbjFU4JqvMwIkMWHp69bmUzG.jpg', 'https://www.youtube.com/watch?v=dcUOO4Itgmw', 'Fernando Meirelles'),
(1030, 'Life Is Beautiful', 'An unforgettable fable that proves love, family and imagination conquer all.', 'A Jewish-Italian waiter creates a fantasy game for his young son to shield him from the horrors of a concentration camp.', '1997-12-20', 116, 'https://image.tmdb.org/t/p/w500/74hLDKjD5aGYOotO6esUVaeISa2.jpg', 'https://image.tmdb.org/t/p/original/6aNKD81RHR1DqUUa8kOZ1TBY1Lp.jpg', 'https://www.youtube.com/watch?v=16RZF50VbdE', 'Roberto Benigni'),
(1031, 'The Green Mile', 'Miracles do happen.', 'A supernatural tale about sacred miracles occurring within a death row facility in a Southern prison.', '1999-12-10', 189, 'https://image.tmdb.org/t/p/w500/8VG8fDNiy50H4FedGwdSVUPoaJe.jpg', 'https://image.tmdb.org/t/p/original/amZavErrjrdgDwhsIdpWxHNenIx.jpg', 'https://www.youtube.com/watch?v=Ki4haFrqSrw', 'Frank Darabont'),
(1032, 'Princess Mononoke', 'Live on.', 'On a journey to find the cure for a Tatarigami curse, Ashitaka finds himself in the middle of a war between the forest gods and Tatara, a mining colony.', '1997-07-12', 134, 'https://image.tmdb.org/t/p/w500/cMYCDADoLKLbB83g4WnJegaZimC.jpg', 'https://image.tmdb.org/t/p/original/6pAig3kYqN2s7nQo8t07zX0Yn2H.jpg', 'https://www.youtube.com/watch?v=4OiMOHRDs14', 'Hayao Miyazaki'),
(1033, 'Saving Private Ryan', 'The mission is a man.', 'Following the Normandy Landings, a group of U.S. soldiers go behind enemy lines to retrieve a paratrooper whose brothers have been killed in action.', '1998-07-24', 169, 'https://image.tmdb.org/t/p/w500/uqx37cS8cpHg8U35f9U5IBlrCV3.jpg', 'https://image.tmdb.org/t/p/original/bdD39MpSVhKjxarTxLSfX6baoMP.jpg', 'https://www.youtube.com/watch?v=9CiW_D5FJaY', 'Steven Spielberg'),
(1034, 'Spider-Man: No Way Home', 'The Multiverse unleashed.', 'With Spider-Man''s identity now revealed, Peter asks Doctor Strange for help. When a spell goes wrong, dangerous foes from other worlds appear.', '2021-12-17', 148, 'https://image.tmdb.org/t/p/w500/1g0dhYtq4irTY1GPXvft6k4YLjm.jpg', 'https://image.tmdb.org/t/p/original/uyrOU4BDm2kbVxFsMiDFIHDhc4d.jpg', 'https://www.youtube.com/watch?v=JfVOs4VSpmA', 'Jon Watts'),
(1035, 'Avengers: Endgame', 'Part of the journey is the end.', 'After the devastating events of Infinity War, the universe is in ruins. With the help of remaining allies, the Avengers assemble once more to reverse Thanos'' actions.', '2019-04-26', 181, 'https://image.tmdb.org/t/p/w500/ulzhLuWrPK07P1YkdWQLZnQh1JL.jpg', 'https://image.tmdb.org/t/p/original/7RyHsO4yDXtBv1zUU3mTpHeQ0d5.jpg', 'https://www.youtube.com/watch?v=TcMBFSGVi1c', 'Anthony Russo'),
(1036, 'Avengers: Infinity War', 'An entire universe. Once and for all.', 'The Avengers and their allies must be willing to sacrifice all in an attempt to defeat the powerful Thanos before his blitz of devastation puts an end to the universe.', '2018-04-27', 149, 'https://image.tmdb.org/t/p/w500/7WsyChQLEftFiDOVTGkv3hFpyyt.jpg', 'https://image.tmdb.org/t/p/original/mDfJG3LC3Dqb67AZ52x3Z0jU0uB.jpg', 'https://www.youtube.com/watch?v=6ZfuNTqbHE8', 'Anthony Russo'),
(1037, 'Top Gun: Maverick', 'Feel the need. The need for speed.', 'After thirty years, Maverick is still pushing the envelope as a top naval aviator, but must confront ghosts of his past when he leads TOP GUN''s elite graduates.', '2022-05-27', 130, 'https://image.tmdb.org/t/p/w500/n0YuM4f5lvGAP6MAW2kBIzugXnc.jpg', 'https://image.tmdb.org/t/p/original/AaV1YIdWKnjAIAOe8UUKBFm327v.jpg', 'https://www.youtube.com/watch?v=giXco2jaZ_4', 'Joseph Kosinski'),
